mapper.delete:
delete
from `corgi`.`corgi_activity_like`
where activity_id = #{activityId}

    and like_user_id = #{userId}

mapper.select:
select count(1)
from corgi_activity_like
where activity_id = #{activityId}

select count(1)
from corgi_activity_like
where activity_id = #{activityId}
  and like_user_id = #{userId}

select count(1)
from corgi_activity_like l
where l.ctime > #{user.ctime}
  and l.user_id = #{user.userId}

select l.activity_id
from corgi_activity_like l
left join corgi_activity_creator c on c.activity_id = l.activity_id
where l.like_user_id = #{userId}

    and l.id < (select id from corgi_activity_like where like_user_id = #{userId} and activity_id = #{activityId})


    and c.category = #{category}

order by l.id DESC
    limit #{start}, #{size}

select

from corgi_activity_like
where like_user_id = #{like.likeUserId}
and user_id != #{like.likeUserId}
and ctime < #{like.ctime}
order by id desc
limit #{size}

select count(1)
from corgi_activity_like
where user_id = #{userId}

    and type = 'real'
    and ctime > #{date}
